package com.moodtools.hub

internal object LauncherTranslationChunk8 {
    val entries = mapOf(
        "The legacy launcher data handoff will be retried." to arrayOf("Ang paglilipat ng legacy launcher data ay susubukang muli.", "\uC774\uC804 \uB7F0\uCC98 \uB370\uC774\uD130 \uC804\uB2EC\uC774 \uB2E4\uC2DC \uC2DC\uB3C4\uB429\uB2C8\uB2E4.", "\u30EC\u30AC\u30B7\u30FC\u30E9\u30F3\u30C1\u30E3\u30FC\u30C7\u30FC\u30BF\u306E\u5F15\u304D\u7D99\u304E\u3092\u518D\u8A66\u884C\u3057\u307E\u3059\u3002", "\u4F20\u7EDF\u542F\u52A8\u5668\u6570\u636E\u4F20\u9012\u5C06\u91CD\u8BD5\u3002", "Se volver\u00E1 a intentar la transferencia de datos del lanzador heredado.", "Vi\u1EC7c chuy\u1EC3n d\u1EEF li\u1EC7u tr\u00ECnh kh\u1EDFi ch\u1EA1y c\u0169 s\u1EBD \u0111\u01B0\u1EE3c th\u1EED l\u1EA1i.", "Penyerahan data peluncur lama akan dicoba ulang.", "A transfer\u00EAncia de dados do launcher legado ser\u00E1 tentada novamente."),
        "The next Play starts with fresh game data." to arrayOf("Ang susunod na Play ay magsisimula sa sariwang data ng laro.", "\uB2E4\uC74C \uD50C\uB808\uC774\uB294 \uC0C8\uB85C\uC6B4 \uAC8C\uC784 \uB370\uC774\uD130\uB85C \uC2DC\uC791\uB429\uB2C8\uB2E4.", "\u6B21\u56DE\u306E\u30D7\u30EC\u30A4\u306F\u65B0\u3057\u3044\u30B2\u30FC\u30E0\u30C7\u30FC\u30BF\u3067\u958B\u59CB\u3055\u308C\u307E\u3059\u3002", "\u4E0B\u4E00\u6B21\u6E38\u73A9\u5C06\u4F7F\u7528\u5168\u65B0\u7684\u6E38\u620F\u6570\u636E\u5F00\u59CB\u3002", "La pr\u00F3xima partida comenzar\u00E1 con datos del juego nuevos.", "L\u01B0\u1EE3t ch\u01A1i ti\u1EBFp theo s\u1EBD b\u1EAFt \u0111\u1EA7u v\u1EDBi d\u1EEF li\u1EC7u tr\u00F2 ch\u01A1i m\u1EDBi.", "Permainan berikutnya dimulai dengan data permainan yang baru.", "O pr\u00F3ximo jogo come\u00E7a com dados de jogo novos."),
        "The next Play will create a fresh managed installation." to arrayOf("Ang susunod na Play ay lilikha ng bagong managed installation.", "\uB2E4\uC74C \uD50C\uB808\uC774\uB294 \uC0C8\uB85C\uC6B4 \uAD00\uB9AC \uC124\uCE58\uB97C \uC0DD\uC131\uD569\uB2C8\uB2E4.", "\u6B21\u56DE\u306E\u30D7\u30EC\u30A4\u3067\u306F\u65B0\u3057\u3044\u7BA1\u7406\u3055\u308C\u305F\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u304C\u4F5C\u6210\u3055\u308C\u307E\u3059\u3002", "\u4E0B\u4E00\u6B21\u6E38\u73A9\u5C06\u521B\u5EFA\u5168\u65B0\u7684\u53D7\u7BA1\u7406\u5B89\u88C5\u3002", "La pr\u00F3xima partida crear\u00E1 una instalaci\u00F3n gestionada nueva.", "L\u01B0\u1EE3t ch\u01A1i ti\u1EBFp theo s\u1EBD t\u1EA1o m\u1ED9t c\u00E0i \u0111\u1EB7t qu\u1EA3n l\u00FD m\u1EDBi.", "Permainan berikutnya akan membuat instalasi terkelola yang baru.", "O pr\u00F3ximo jogo criar\u00E1 uma nova instala\u00E7\u00E3o gerenciada."),
        "The operation did not finish. Open Diagnostics for the recorded cause, then try again." to arrayOf("Hindi natapos ang operasyon. Buksan ang Diagnostics para sa naitalang sanhi, pagkatapos subukang muli.", "\uC791\uC5C5\uC774 \uC644\uB8CC\uB418\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4. \uAE30\uB85D\uB41C \uC6D0\uC778\uC744 \uD655\uC778\uD558\uB824\uBA74 \uC9C4\uB2E8\uC744 \uC5F4\uACE0 \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694.", "\u64CD\u4F5C\u306F\u7D42\u4E86\u3057\u307E\u305B\u3093\u3067\u3057\u305F\u3002[\u8A3A\u65AD]\u3092\u958B\u3044\u3066\u8A18\u9332\u3055\u308C\u305F\u539F\u56E0\u3092\u78BA\u8A8D\u3057\u3001\u518D\u5EA6\u8A66\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "\u64CD\u4F5C\u672A\u5B8C\u6210\u3002\u8BF7\u6253\u5F00\u8BCA\u65AD\u4EE5\u67E5\u770B\u8BB0\u5F55\u7684\u539F\u56E0\uFF0C\u7136\u540E\u91CD\u8BD5\u3002", "La operaci\u00F3n no termin\u00F3. Abre Diagn\u00F3sticos para la causa registrada, luego intenta de nuevo.", "Ho\u1EA1t \u0111\u1ED9ng ch\u01B0a ho\u00E0n t\u1EA5t. M\u1EDF Ch\u1EA9n \u0111o\u00E1n \u0111\u1EC3 xem nguy\u00EAn nh\u00E2n \u0111\u00E3 ghi, sau \u0111\u00F3 th\u1EED l\u1EA1i.", "Operasi tidak selesai. Buka Diagnostik untuk penyebab yang tercatat, lalu coba lagi.", "A opera\u00E7\u00E3o n\u00E3o foi conclu\u00EDda. Abra Diagn\u00F3sticos para a causa registrada, depois tente novamente."),
        "The original package is currently absent, so the prepared package was kept. Try again without downloading the game." to arrayOf("Ang orihinal na package ay kasalukuyang wala, kaya ang inihandang package ay itinatag. Subukang muli nang hindi nagda-download ng laro.", "\uC6D0\uBCF8 \uD328\uD0A4\uC9C0\uAC00 \uD604\uC7AC \uC5C6\uC73C\uBBC0\uB85C \uC900\uBE44\uB41C \uD328\uD0A4\uC9C0\uAC00 \uBCF4\uAD00\uB418\uC5C8\uC2B5\uB2C8\uB2E4. \uAC8C\uC784\uC744 \uB2E4\uC6B4\uB85C\uB4DC\uD558\uC9C0 \uC54A\uACE0 \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694.", "\u5143\u306E\u30D1\u30C3\u30B1\u30FC\u30B8\u304C\u73FE\u5728\u5B58\u5728\u3057\u306A\u3044\u305F\u3081\u3001\u6E96\u5099\u3055\u308C\u305F\u30D1\u30C3\u30B1\u30FC\u30B8\u304C\u4FDD\u6301\u3055\u308C\u307E\u3057\u305F\u3002\u30B2\u30FC\u30E0\u3092\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u305B\u305A\u306B\u518D\u8A66\u884C\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "\u539F\u59CB\u5B89\u88C5\u5305\u5F53\u524D\u4E0D\u5B58\u5728\uFF0C\u56E0\u6B64\u5DF2\u4FDD\u7559\u5DF2\u51C6\u5907\u7684\u5B89\u88C5\u5305\u3002\u65E0\u9700\u91CD\u65B0\u4E0B\u8F7D\u6E38\u620F\u5373\u53EF\u91CD\u8BD5\u3002", "El paquete original actualmente no est\u00E1 presente, por lo que se mantuvo el paquete preparado. Intenta de nuevo sin descargar el juego.", "G\u00F3i g\u1ED1c hi\u1EC7n kh\u00F4ng c\u00F3, v\u00EC v\u1EADy g\u00F3i \u0111\u00E3 chu\u1EA9n b\u1ECB \u0111\u01B0\u1EE3c gi\u1EEF l\u1EA1i. Th\u1EED l\u1EA1i m\u00E0 kh\u00F4ng t\u1EA3i tr\u00F2 ch\u01A1i xu\u1ED1ng.", "Paket asli saat ini tidak ada, jadi paket yang disiapkan disimpan. Coba lagi tanpa mengunduh permainan.", "O pacote original est\u00E1 atualmente ausente, ent\u00E3o o pacote preparado foi mantido. Tente novamente sem baixar o jogo."),
        "The other selected add-ons were removed. Restart Jester Mods and try the remaining selection again." to arrayOf("Ang iba pang piniling add-ons ay tinanggal. I-restart ang Jester Mods at subukang muli ang natitirang pagpili.", "\uB2E4\uB978 \uC120\uD0DD\uD55C \uCD94\uAC00 \uAE30\uB2A5\uC774 \uC81C\uAC70\uB418\uC5C8\uC2B5\uB2C8\uB2E4. Jester Mods\uB97C \uB2E4\uC2DC \uC2DC\uC791\uD558\uACE0 \uB0A8\uC740 \uC120\uD0DD \uD56D\uBAA9\uC744 \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694.", "\u4ED6\u306E\u9078\u629E\u3055\u308C\u305F\u30A2\u30C9\u30AA\u30F3\u306F\u524A\u9664\u3055\u308C\u307E\u3057\u305F\u3002Jester Mods\u3092\u518D\u8D77\u52D5\u3057\u3066\u3001\u6B8B\u308A\u306E\u9078\u629E\u3092\u518D\u8A66\u884C\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "\u5176\u4ED6\u5DF2\u9009\u62E9\u7684\u9644\u52A0\u7EC4\u4EF6\u5DF2\u88AB\u79FB\u9664\u3002\u91CD\u65B0\u542F\u52A8 Jester Mods \u5E76\u91CD\u8BD5\u5269\u4F59\u7684\u9009\u62E9\u3002", "Los otros complementos seleccionados fueron eliminados. Reinicia Jester Mods y vuelve a intentar la selecci\u00F3n restante.", "C\u00E1c ti\u1EC7n \u00EDch b\u1ED5 sung kh\u00E1c \u0111\u01B0\u1EE3c ch\u1ECDn \u0111\u00E3 b\u1ECB x\u00F3a. Kh\u1EDFi \u0111\u1ED9ng l\u1EA1i Jester Mods v\u00E0 th\u1EED l\u1EA1i c\u00E1c l\u1EF1a ch\u1ECDn c\u00F2n l\u1EA1i.", "Add-on lain yang dipilih telah dihapus. Mulai ulang Jester Mods dan coba lagi pilihan yang tersisa.", "Os outros complementos selecionados foram removidos. Reinicie o Jester Mods e tente novamente a sele\u00E7\u00E3o restante."),
        "The package will be verified before Android can open it." to arrayOf("Ang package ay susuriin bago ito mabuksan ng Android.", "\uD328\uD0A4\uC9C0\uB294 Android\uC5D0\uC11C \uC5F4\uAE30 \uC804\uC5D0 \uD655\uC778\uB429\uB2C8\uB2E4.", "Android\u304C\u958B\u304F\u524D\u306B\u30D1\u30C3\u30B1\u30FC\u30B8\u304C\u8A8D\u8A3C\u3055\u308C\u307E\u3059\u3002", "\u5728 Android \u6253\u5F00\u524D\uFF0C\u5B89\u88C5\u5305\u5C06\u88AB\u9A8C\u8BC1\u3002", "El paquete ser\u00E1 verificado antes de que Android pueda abrirlo.", "G\u00F3i s\u1EBD \u0111\u01B0\u1EE3c x\u00E1c minh tr\u01B0\u1EDBc khi Android c\u00F3 th\u1EC3 m\u1EDF n\u00F3.", "Paket akan diverifikasi sebelum Android dapat membukanya.", "O pacote ser\u00E1 verificado antes que o Android possa abri-lo."),
        "The partial package was kept safely, so a future retry can resume faster." to arrayOf("Ang bahagi ng pakete ay ligtas na naitabi, kaya mas mabilis na makakapagpatuloy sa susunod na pagtatangka.", "\uBD80\uBD84 \uD328\uD0A4\uC9C0\uB294 \uC548\uC804\uD558\uAC8C \uBCF4\uAD00\uB418\uC5C8\uC73C\uBBC0\uB85C, \uB098\uC911\uC5D0 \uC7AC\uC2DC\uB3C4\uD560 \uB54C \uB354 \uBE68\uB9AC \uC774\uC5B4\uC11C \uC9C4\uD589\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\u90E8\u5206\u7684\u306A\u30D1\u30C3\u30B1\u30FC\u30B8\u306F\u5B89\u5168\u306B\u4FDD\u5B58\u3055\u308C\u3066\u3044\u308B\u305F\u3081\u3001\u5C06\u6765\u306E\u518D\u8A66\u884C\u306F\u3088\u308A\u65E9\u304F\u518D\u958B\u3067\u304D\u307E\u3059\u3002", "\u90E8\u5206\u5B89\u88C5\u5305\u5DF2\u5B89\u5168\u4FDD\u5B58\uFF0C\u56E0\u6B64\u5C06\u6765\u91CD\u8BD5\u65F6\u53EF\u4EE5\u66F4\u5FEB\u6062\u590D\u3002", "El paquete parcial se mantuvo de forma segura, por lo que un reintento futuro puede reanudarse m\u00E1s r\u00E1pido.", "G\u00F3i m\u1ED9t ph\u1EA7n \u0111\u00E3 \u0111\u01B0\u1EE3c gi\u1EEF an to\u00E0n, v\u00EC v\u1EADy l\u1EA7n th\u1EED l\u1EA1i trong t\u01B0\u01A1ng lai c\u00F3 th\u1EC3 ti\u1EBFp t\u1EE5c nhanh h\u01A1n.", "Paket sebagian disimpan dengan aman, sehingga percobaan ulang di masa depan bisa dilanjutkan lebih cepat.", "O pacote parcial foi mantido com seguran\u00E7a, para que uma nova tentativa futura possa ser retomada mais rapidamente."),
        "The partial package was kept safely, so the next attempt can resume faster." to arrayOf("Ang bahagi ng pakete ay ligtas na naitabi, kaya mas mabilis na makakapagpatuloy sa susunod na pagtatangka.", "\uBD80\uBD84 \uD328\uD0A4\uC9C0\uB294 \uC548\uC804\uD558\uAC8C \uBCF4\uAD00\uB418\uC5C8\uC73C\uBBC0\uB85C, \uB2E4\uC74C \uC2DC\uB3C4\uC5D0\uC11C \uB354 \uBE68\uB9AC \uC774\uC5B4\uC11C \uC9C4\uD589\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\u90E8\u5206\u7684\u306A\u30D1\u30C3\u30B1\u30FC\u30B8\u306F\u5B89\u5168\u306B\u4FDD\u5B58\u3055\u308C\u3066\u3044\u308B\u305F\u3081\u3001\u6B21\u306E\u8A66\u884C\u306F\u3088\u308A\u65E9\u304F\u518D\u958B\u3067\u304D\u307E\u3059\u3002", "\u90E8\u5206\u5B89\u88C5\u5305\u5DF2\u5B89\u5168\u4FDD\u5B58\uFF0C\u56E0\u6B64\u4E0B\u4E00\u6B21\u5C1D\u8BD5\u65F6\u53EF\u4EE5\u66F4\u5FEB\u6062\u590D\u3002", "El paquete parcial se mantuvo de forma segura, por lo que el pr\u00F3ximo intento puede reanudarse m\u00E1s r\u00E1pido.", "G\u00F3i m\u1ED9t ph\u1EA7n \u0111\u00E3 \u0111\u01B0\u1EE3c gi\u1EEF an to\u00E0n, v\u00EC v\u1EADy l\u1EA7n th\u1EED ti\u1EBFp theo c\u00F3 th\u1EC3 ti\u1EBFp t\u1EE5c nhanh h\u01A1n.", "Paket sebagian disimpan dengan aman, sehingga upaya berikutnya bisa dilanjutkan lebih cepat.", "O pacote parcial foi mantido com seguran\u00E7a, para que a pr\u00F3xima tentativa possa ser retomada mais rapidamente."),
        "The patched game is ready. Open it from your Library when you want to play." to arrayOf("Handa na ang pinaayos na laro. Buksan ito mula sa iyong Library kapag nais mong maglaro.", "\uD328\uCE58\uB41C \uAC8C\uC784\uC774 \uC900\uBE44\uB418\uC5C8\uC2B5\uB2C8\uB2E4. \uD50C\uB808\uC774\uD558\uACE0 \uC2F6\uC744 \uB54C \uB77C\uC774\uBE0C\uB7EC\uB9AC\uC5D0\uC11C \uC5F4\uC5B4\uBCF4\uC138\uC694.", "\u30D1\u30C3\u30C1\u6E08\u307F\u306E\u30B2\u30FC\u30E0\u304C\u6E96\u5099\u3067\u304D\u307E\u3057\u305F\u3002\u30D7\u30EC\u30A4\u3057\u305F\u3044\u3068\u304D\u306B\u30E9\u30A4\u30D6\u30E9\u30EA\u304B\u3089\u958B\u3044\u3066\u304F\u3060\u3055\u3044\u3002", "\u5DF2\u4FEE\u8865\u7684\u6E38\u620F\u5DF2\u51C6\u5907\u597D\u3002\u60F3\u73A9\u65F6\u8BF7\u4ECE\u60A8\u7684\u5E93\u4E2D\u6253\u5F00\u5B83\u3002", "El juego parcheado est\u00E1 listo. \u00C1brelo desde tu Biblioteca cuando quieras jugar.", "Tr\u00F2 ch\u01A1i \u0111\u00E3 \u0111\u01B0\u1EE3c v\u00E1 \u0111\u00E3 s\u1EB5n s\u00E0ng. M\u1EDF n\u00F3 t\u1EEB Th\u01B0 vi\u1EC7n c\u1EE7a b\u1EA1n khi b\u1EA1n mu\u1ED1n ch\u01A1i.", "Game yang sudah dipatch siap. Buka dari Perpustakaan Anda ketika Anda ingin bermain.", "O jogo com patch est\u00E1 pronto. Abra-o na sua Biblioteca quando quiser jogar."),
        "The prepared package could not be retained safely for installation." to arrayOf("Ang hinanda na pakete ay hindi naiimbak nang ligtas para sa pag-install.", "\uC900\uBE44\uB41C \uD328\uD0A4\uC9C0\uB97C \uC124\uCE58\uC6A9\uC73C\uB85C \uC548\uC804\uD558\uAC8C \uBCF4\uAD00\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.", "\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u306E\u305F\u3081\u306B\u6E96\u5099\u3055\u308C\u305F\u30D1\u30C3\u30B1\u30FC\u30B8\u306F\u5B89\u5168\u306B\u4FDD\u6301\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F\u3002", "\u51C6\u5907\u597D\u7684\u5B89\u88C5\u5305\u65E0\u6CD5\u5B89\u5168\u4FDD\u7559\u4EE5\u4F9B\u5B89\u88C5\u3002", "No se pudo conservar de forma segura el paquete preparado para la instalaci\u00F3n.", "G\u00F3i \u0111\u00E3 chu\u1EA9n b\u1ECB kh\u00F4ng th\u1EC3 \u0111\u01B0\u1EE3c gi\u1EEF an to\u00E0n \u0111\u1EC3 c\u00E0i \u0111\u1EB7t.", "Paket yang disiapkan tidak dapat disimpan dengan aman untuk instalasi.", "O pacote preparado n\u00E3o p\u00F4de ser mantido com seguran\u00E7a para instala\u00E7\u00E3o."),
        "The prepared package is ready to retry." to arrayOf("Handa na ang hinanda na pakete para subukang muli.", "\uC900\uBE44\uB41C \uD328\uD0A4\uC9C0\uB294 \uC7AC\uC2DC\uB3C4\uD560 \uC900\uBE44\uAC00 \uB418\uC5B4 \uC788\uC2B5\uB2C8\uB2E4.", "\u6E96\u5099\u3055\u308C\u305F\u30D1\u30C3\u30B1\u30FC\u30B8\u306F\u518D\u8A66\u884C\u3059\u308B\u6E96\u5099\u304C\u3067\u304D\u3066\u3044\u307E\u3059\u3002", "\u51C6\u5907\u597D\u7684\u5B89\u88C5\u5305\u5DF2\u51C6\u5907\u597D\u91CD\u8BD5\u3002", "El paquete preparado est\u00E1 listo para reintentarse.", "G\u00F3i \u0111\u00E3 chu\u1EA9n b\u1ECB s\u1EB5n s\u00E0ng \u0111\u1EC3 th\u1EED l\u1EA1i.", "Paket yang disiapkan siap untuk dicoba ulang.", "O pacote preparado est\u00E1 pronto para nova tentativa."),
        "The prepared package remains available and the original game does not need to be downloaded again." to arrayOf("Mananatiling magagamit ang hinanda na pakete at hindi na kailangan i-download muli ang orihinal na laro.", "\uC900\uBE44\uB41C \uD328\uD0A4\uC9C0\uB294 \uC5EC\uC804\uD788 \uC774\uC6A9 \uAC00\uB2A5\uD558\uBA70, \uC6D0\uBCF8 \uAC8C\uC784\uC744 \uB2E4\uC2DC \uB2E4\uC6B4\uB85C\uB4DC\uD560 \uD544\uC694\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4.", "\u6E96\u5099\u3055\u308C\u305F\u30D1\u30C3\u30B1\u30FC\u30B8\u306F\u5F15\u304D\u7D9A\u304D\u5229\u7528\u53EF\u80FD\u3067\u3042\u308A\u3001\u5143\u306E\u30B2\u30FC\u30E0\u3092\u518D\u5EA6\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u3059\u308B\u5FC5\u8981\u306F\u3042\u308A\u307E\u305B\u3093\u3002", "\u51C6\u5907\u597D\u7684\u5B89\u88C5\u5305\u4ECD\u7136\u53EF\u7528\uFF0C\u5E76\u4E14\u4E0D\u9700\u8981\u518D\u6B21\u4E0B\u8F7D\u539F\u59CB\u6E38\u620F\u3002", "El paquete preparado sigue disponible y no es necesario descargar nuevamente el juego original.", "G\u00F3i \u0111\u00E3 chu\u1EA9n b\u1ECB v\u1EABn kh\u1EA3 d\u1EE5ng v\u00E0 tr\u00F2 ch\u01A1i g\u1ED1c kh\u00F4ng c\u1EA7n ph\u1EA3i t\u1EA3i xu\u1ED1ng l\u1EA1i.", "Paket yang disiapkan tetap tersedia dan game asli tidak perlu diunduh lagi.", "O pacote preparado permanece dispon\u00EDvel e o jogo original n\u00E3o precisa ser baixado novamente."),
        "The previous direct patch must be removed before the exact-package shell can be created." to arrayOf("Kailangang tanggalin ang nakaraang direktang patch bago malikha ang exact-package shell.", "\uC815\uD655\uD55C \uD328\uD0A4\uC9C0 \uC178\uC744 \uB9CC\uB4E4\uB824\uBA74 \uC774\uC804 \uC9C1\uC811 \uD328\uCE58\uB97C \uC81C\uAC70\uD574\uC57C \uD569\uB2C8\uB2E4.", "\u6B63\u78BA\u306A\u30D1\u30C3\u30B1\u30FC\u30B8\u306E\u30B7\u30A7\u30EB\u3092\u4F5C\u6210\u3059\u308B\u524D\u306B\u3001\u524D\u56DE\u306E\u76F4\u63A5\u30D1\u30C3\u30C1\u3092\u524A\u9664\u3059\u308B\u5FC5\u8981\u304C\u3042\u308A\u307E\u3059\u3002", "\u5FC5\u987B\u5220\u9664\u4E4B\u524D\u7684\u76F4\u63A5\u8865\u4E01\uFF0C\u7136\u540E\u624D\u80FD\u521B\u5EFA\u7CBE\u786E\u5B89\u88C5\u5305\u5916\u58F3\u3002", "El parche directo anterior debe eliminarse antes de que se pueda crear el paquete exacto.", "B\u1EA3n v\u00E1 tr\u1EF1c ti\u1EBFp tr\u01B0\u1EDBc \u0111\u00F3 ph\u1EA3i \u0111\u01B0\u1EE3c g\u1EE1 b\u1ECF tr\u01B0\u1EDBc khi c\u00F3 th\u1EC3 t\u1EA1o v\u1ECF g\u00F3i ch\u00EDnh x\u00E1c.", "Patch langsung sebelumnya harus dihapus sebelum shell paket tepat dapat dibuat.", "O patch direto anterior deve ser removido antes que o shell de pacote exato possa ser criado."),
        "The previous patch could not be removed." to arrayOf("Hindi natanggal ang nakaraang patch.", "\uC774\uC804 \uD328\uCE58\uB97C \uC81C\uAC70\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.", "\u524D\u56DE\u306E\u30D1\u30C3\u30C1\u3092\u524A\u9664\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F\u3002", "\u65E0\u6CD5\u5220\u9664\u4E4B\u524D\u7684\u8865\u4E01\u3002", "No se pudo eliminar el parche anterior.", "B\u1EA3n v\u00E1 tr\u01B0\u1EDBc \u0111\u00F3 kh\u00F4ng th\u1EC3 b\u1ECB g\u1EE1 b\u1ECF.", "Patch sebelumnya tidak dapat dihapus.", "O patch anterior n\u00E3o p\u00F4de ser removido."),
        "The previous patch remains installed. You can restore the official game whenever you're ready." to arrayOf("Nanatiling naka-install ang nakaraang patch. Maaari mong maibalik ang opisyal na laro kapag handa ka na.", "\uC774\uC804 \uD328\uCE58\uB294 \uC5EC\uC804\uD788 \uC124\uCE58\uB418\uC5B4 \uC788\uC2B5\uB2C8\uB2E4. \uC900\uBE44\uAC00 \uB418\uBA74 \uACF5\uC2DD \uAC8C\uC784\uC73C\uB85C \uBCF5\uC6D0\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\u524D\u56DE\u306E\u30D1\u30C3\u30C1\u306F\u5F15\u304D\u7D9A\u304D\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3055\u308C\u3066\u3044\u307E\u3059\u3002\u6E96\u5099\u304C\u3067\u304D\u305F\u3089\u516C\u5F0F\u30B2\u30FC\u30E0\u3092\u5FA9\u5143\u3067\u304D\u307E\u3059\u3002", "\u4E4B\u524D\u7684\u8865\u4E01\u4ECD\u7136\u5DF2\u5B89\u88C5\u3002\u60A8\u53EF\u4EE5\u968F\u65F6\u6062\u590D\u5B98\u65B9\u6E38\u620F\u3002", "El parche anterior sigue instalado. Puedes restaurar el juego oficial cuando quieras.", "B\u1EA3n v\u00E1 tr\u01B0\u1EDBc \u0111\u00F3 v\u1EABn c\u00F2n \u0111\u01B0\u1EE3c c\u00E0i \u0111\u1EB7t. B\u1EA1n c\u00F3 th\u1EC3 kh\u00F4i ph\u1EE5c tr\u00F2 ch\u01A1i ch\u00EDnh th\u1EE9c b\u1EA5t c\u1EE9 khi n\u00E0o s\u1EB5n s\u00E0ng.", "Patch sebelumnya tetap terinstal. Anda dapat memulihkan game resmi kapan saja Anda siap.", "O patch anterior continua instalado. Voc\u00EA pode restaurar o jogo oficial quando estiver pronto."),
        "The previous {0} patch was not removed. Nothing was changed." to arrayOf("Ang nakaraang {0} patch ay hindi natanggal. Walang nabago.", "\uC774\uC804 {0} \uD328\uCE58\uB294 \uC81C\uAC70\uB418\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4. \uC544\uBB34 \uAC83\uB3C4 \uBCC0\uACBD\uB418\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4.", "\u4EE5\u524D\u306E{0}\u30D1\u30C3\u30C1\u306F\u524A\u9664\u3055\u308C\u307E\u305B\u3093\u3067\u3057\u305F\u3002\u5909\u66F4\u306F\u3042\u308A\u307E\u305B\u3093\u3002", "\u4E4B\u524D\u7684 {0} \u8865\u4E01\u672A\u88AB\u79FB\u9664\u3002\u6CA1\u6709\u4EFB\u4F55\u66F4\u6539\u3002", "El parche anterior {0} no fue eliminado. Nada fue cambiado.", "B\u1EA3n v\u00E1 {0} tr\u01B0\u1EDBc \u0111\u00F3 ch\u01B0a \u0111\u01B0\u1EE3c g\u1EE1 b\u1ECF. Kh\u00F4ng c\u00F3 g\u00EC thay \u0111\u1ED5i.", "Patch {0} sebelumnya tidak dihapus. Tidak ada yang diubah.", "O patch anterior {0} n\u00E3o foi removido. Nada foi alterado."),
        "The previous {0} patch was removed safely. Download its companion game when offered, or choose Google Play." to arrayOf("Ang nakaraang {0} patch ay ligtas na natanggal. I-download ang kaakibat nitong laro kapag inaalok, o piliin ang Google Play.", "\uC774\uC804 {0} \uD328\uCE58\uB294 \uC548\uC804\uD558\uAC8C \uC81C\uAC70\uB418\uC5C8\uC2B5\uB2C8\uB2E4. \uC81C\uACF5\uB420 \uB54C \uD574\uB2F9 \uAC8C\uC784\uC744 \uB2E4\uC6B4\uB85C\uB4DC\uD558\uAC70\uB098 Google Play\uB97C \uC120\uD0DD\uD558\uC138\uC694.", "\u4EE5\u524D\u306E{0}\u30D1\u30C3\u30C1\u306F\u5B89\u5168\u306B\u524A\u9664\u3055\u308C\u307E\u3057\u305F\u3002\u63D0\u4F9B\u3055\u308C\u305F\u5834\u5408\u306F\u305D\u306E\u95A2\u9023\u30B2\u30FC\u30E0\u3092\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u3059\u308B\u304B\u3001Google Play\u3092\u9078\u629E\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "\u4E4B\u524D\u7684 {0} \u8865\u4E01\u5DF2\u5B89\u5168\u79FB\u9664\u3002\u63D0\u4F9B\u65F6\u4E0B\u8F7D\u5176\u914D\u5957\u6E38\u620F\uFF0C\u6216\u9009\u62E9 Google Play\u3002", "El parche anterior {0} fue eliminado de manera segura. Descarga su juego complementario cuando se te ofrezca, o elige Google Play.", "B\u1EA3n v\u00E1 {0} tr\u01B0\u1EDBc \u0111\u00F3 \u0111\u00E3 \u0111\u01B0\u1EE3c g\u1EE1 b\u1ECF an to\u00E0n. T\u1EA3i xu\u1ED1ng tr\u00F2 ch\u01A1i k\u00E8m theo khi \u0111\u01B0\u1EE3c \u0111\u1EC1 ngh\u1ECB, ho\u1EB7c ch\u1ECDn Google Play.", "Patch {0} sebelumnya telah dihapus dengan aman. Unduh game pendampingnya ketika ditawarkan, atau pilih Google Play.", "O patch anterior {0} foi removido com seguran\u00E7a. Baixe seu jogo acompanhante quando for oferecido ou escolha o Google Play."),
        "The private access timer for {0} could not be refreshed." to arrayOf("Hindi ma-refresh ang private access timer para sa {0}.", "{0}\uC5D0 \uB300\uD55C \uAC1C\uC778 \uC811\uADFC \uD0C0\uC774\uBA38\uB97C \uAC31\uC2E0\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.", "{0}\u306E\u30D7\u30E9\u30A4\u30D9\u30FC\u30C8\u30A2\u30AF\u30BB\u30B9\u30BF\u30A4\u30DE\u30FC\u3092\u66F4\u65B0\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F\u3002", "{0} \u7684\u79C1\u4EBA\u8BBF\u95EE\u8BA1\u65F6\u5668\u65E0\u6CD5\u5237\u65B0\u3002", "No se pudo actualizar el temporizador de acceso privado para {0}.", "B\u1ED9 h\u1EB9n gi\u1EDD truy c\u1EADp ri\u00EAng t\u01B0 cho {0} kh\u00F4ng th\u1EC3 \u0111\u01B0\u1EE3c l\u00E0m m\u1EDBi.", "Timer akses pribadi untuk {0} tidak dapat diperbarui.", "O temporizador de acesso privado para {0} n\u00E3o p\u00F4de ser atualizado."),
        "The requested file is not available from the service right now. Open Diagnostics for its response, then try again later." to arrayOf("Ang hinihinging file ay hindi available mula sa serbisyo sa ngayon. Buksan ang Diagnostics para sa tugon nito, pagkatapos subukang muli sa ibang pagkakataon.", "\uC694\uCCAD\uD55C \uD30C\uC77C\uC744 \uD604\uC7AC \uC11C\uBE44\uC2A4\uC5D0\uC11C \uC0AC\uC6A9\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4. \uC9C4\uB2E8\uC744 \uC5F4\uC5B4 \uC751\uB2F5\uC744 \uD655\uC778\uD55C \uB2E4\uC74C, \uB098\uC911\uC5D0 \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694.", "\u8981\u6C42\u3055\u308C\u305F\u30D5\u30A1\u30A4\u30EB\u306F\u73FE\u5728\u30B5\u30FC\u30D3\u30B9\u304B\u3089\u5229\u7528\u3067\u304D\u307E\u305B\u3093\u3002\u8A3A\u65AD\u3092\u958B\u3044\u3066\u305D\u306E\u5FDC\u7B54\u3092\u78BA\u8A8D\u3057\u3001\u5F8C\u3067\u518D\u8A66\u884C\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "\u8BF7\u6C42\u7684\u6587\u4EF6\u5F53\u524D\u65E0\u6CD5\u4ECE\u670D\u52A1\u83B7\u53D6\u3002\u6253\u5F00\u8BCA\u65AD\u67E5\u770B\u5176\u54CD\u5E94\uFF0C\u7136\u540E\u7A0D\u540E\u518D\u8BD5\u3002", "El archivo solicitado no est\u00E1 disponible en el servicio en este momento. Abre Diagn\u00F3sticos para su respuesta y luego int\u00E9ntalo de nuevo m\u00E1s tarde.", "T\u1EC7p \u0111\u01B0\u1EE3c y\u00EAu c\u1EA7u hi\u1EC7n kh\u00F4ng c\u00F3 s\u1EB5n t\u1EEB d\u1ECBch v\u1EE5. M\u1EDF Ch\u1EA9n \u0111o\u00E1n \u0111\u1EC3 xem ph\u1EA3n h\u1ED3i, sau \u0111\u00F3 th\u1EED l\u1EA1i sau.", "File yang diminta tidak tersedia dari layanan saat ini. Buka Diagnostik untuk responsnya, kemudian coba lagi nanti.", "O arquivo solicitado n\u00E3o est\u00E1 dispon\u00EDvel no servi\u00E7o neste momento. Abra Diagn\u00F3stico para a resposta do servi\u00E7o, depois tente novamente mais tarde."),
        "The service asked Jester Mods to slow down. Your saved progress is safe; wait a moment, then retry." to arrayOf("Hiniling ng serbisyo sa Jester Mods na bumagal. Ligtas ang iyong na-save na progreso; maghintay ng sandali, pagkatapos subukang muli.", "\uC11C\uBE44\uC2A4\uC5D0\uC11C Jester Mods\uC5D0\uAC8C \uC18D\uB3C4\uB97C \uB2A6\uCD94\uB77C\uACE0 \uC694\uCCAD\uD588\uC2B5\uB2C8\uB2E4. \uC800\uC7A5\uB41C \uC9C4\uD589 \uC0C1\uD669\uC740 \uC548\uC804\uD569\uB2C8\uB2E4; \uC7A0\uC2DC \uAE30\uB2E4\uB838\uB2E4\uAC00 \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694.", "\u30B5\u30FC\u30D3\u30B9\u304B\u3089Jester Mods\u306B\u30B9\u30ED\u30FC\u30C0\u30A6\u30F3\u3059\u308B\u3088\u3046\u8981\u6C42\u3055\u308C\u307E\u3057\u305F\u3002\u4FDD\u5B58\u3055\u308C\u305F\u9032\u884C\u72B6\u6CC1\u306F\u5B89\u5168\u3067\u3059\u3002\u5C11\u3057\u5F85\u3063\u3066\u304B\u3089\u518D\u8A66\u884C\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "\u670D\u52A1\u8981\u6C42\u5C0F\u4E11Mods\u51CF\u6162\u901F\u5EA6\u3002\u60A8\u7684\u4FDD\u5B58\u8FDB\u5EA6\u662F\u5B89\u5168\u7684\uFF1B\u7B49\u5F85\u7247\u523B\uFF0C\u7136\u540E\u91CD\u8BD5\u3002", "El servicio pidi\u00F3 a Jester Mods que disminuyera la velocidad. Tu progreso guardado est\u00E1 seguro; espera un momento y luego vuelve a intentar.", "D\u1ECBch v\u1EE5 y\u00EAu c\u1EA7u Jester Mods gi\u1EA3m t\u1ED1c. Ti\u1EBFn tr\u00ECnh \u0111\u00E3 l\u01B0u c\u1EE7a b\u1EA1n an to\u00E0n; \u0111\u1EE3i m\u1ED9t l\u00FAc, sau \u0111\u00F3 th\u1EED l\u1EA1i.", "Layanan meminta Jester Mods untuk memperlambat. Kemajuan yang disimpan aman; tunggu sebentar, lalu coba lagi.", "O servi\u00E7o pediu ao Jester Mods para desacelerar. Seu progresso salvo est\u00E1 seguro; espere um momento e tente novamente."),
        "The verified download is saved on this device." to arrayOf("Ang na-verify na download ay naka-save sa device na ito.", "\uAC80\uC99D\uB41C \uB2E4\uC6B4\uB85C\uB4DC\uAC00 \uC774 \uAE30\uAE30\uC5D0 \uC800\uC7A5\uB418\uC5C8\uC2B5\uB2C8\uB2E4.", "\u691C\u8A3C\u6E08\u307F\u306E\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u306F\u3053\u306E\u30C7\u30D0\u30A4\u30B9\u306B\u4FDD\u5B58\u3055\u308C\u3066\u3044\u307E\u3059\u3002", "\u5DF2\u5728\u6B64\u8BBE\u5907\u4E0A\u4FDD\u5B58\u5DF2\u9A8C\u8BC1\u7684\u4E0B\u8F7D\u6587\u4EF6\u3002", "La descarga verificada est\u00E1 guardada en este dispositivo.", "T\u1EC7p t\u1EA3i xu\u1ED1ng \u0111\u00E3 \u0111\u01B0\u1EE3c x\u00E1c minh \u0111\u01B0\u1EE3c l\u01B0u tr\u00EAn thi\u1EBFt b\u1ECB n\u00E0y.", "Unduhan yang diverifikasi telah tersimpan di perangkat ini.", "O download verificado est\u00E1 salvo neste dispositivo."),
        "The verified installer will open automatically." to arrayOf("Ang na-verify na installer ay automatic na bubukas.", "\uAC80\uC99D\uB41C \uC124\uCE58 \uAD00\uB9AC\uC790\uAC00 \uC790\uB3D9\uC73C\uB85C \uC5F4\uB9BD\uB2C8\uB2E4.", "\u691C\u8A3C\u6E08\u307F\u306E\u30A4\u30F3\u30B9\u30C8\u30FC\u30E9\u30FC\u306F\u81EA\u52D5\u7684\u306B\u958B\u304D\u307E\u3059\u3002", "\u5DF2\u9A8C\u8BC1\u7684\u5B89\u88C5\u7A0B\u5E8F\u5C06\u81EA\u52A8\u6253\u5F00\u3002", "El instalador verificado se abrir\u00E1 autom\u00E1ticamente.", "Tr\u00ECnh c\u00E0i \u0111\u1EB7t \u0111\u00E3 \u0111\u01B0\u1EE3c x\u00E1c minh s\u1EBD m\u1EDF t\u1EF1 \u0111\u1ED9ng.", "Penginstal yang diverifikasi akan terbuka secara otomatis.", "O instalador verificado ser\u00E1 aberto automaticamente."),
        "The verified package is still saved. Restart the device and try opening Android's installer again." to arrayOf("Ang na-verify na package ay naka-save pa rin. I-restart ang device at subukang muli buksan ang installer ng Android.", "\uAC80\uC99D\uB41C \uD328\uD0A4\uC9C0\uAC00 \uC5EC\uC804\uD788 \uC800\uC7A5\uB418\uC5B4 \uC788\uC2B5\uB2C8\uB2E4. \uAE30\uAE30\uB97C \uC7AC\uC2DC\uC791\uD55C \uD6C4 Android \uC124\uCE58 \uAD00\uB9AC\uC790\uB97C \uB2E4\uC2DC \uC5F4\uC5B4\uBCF4\uC138\uC694.", "\u691C\u8A3C\u6E08\u307F\u306E\u30D1\u30C3\u30B1\u30FC\u30B8\u306F\u307E\u3060\u4FDD\u5B58\u3055\u308C\u3066\u3044\u307E\u3059\u3002\u30C7\u30D0\u30A4\u30B9\u3092\u518D\u8D77\u52D5\u3057\u3066\u3001Android\u306E\u30A4\u30F3\u30B9\u30C8\u30FC\u30E9\u30FC\u3092\u518D\u8A66\u884C\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "\u5DF2\u9A8C\u8BC1\u7684\u5B89\u88C5\u5305\u4ECD\u7136\u4FDD\u5B58\u3002\u91CD\u542F\u8BBE\u5907\u5E76\u518D\u6B21\u5C1D\u8BD5\u6253\u5F00 Android \u5B89\u88C5\u7A0B\u5E8F\u3002", "El paquete verificado todav\u00EDa est\u00E1 guardado. Reinicia el dispositivo e intenta abrir el instalador de Android nuevamente.", "G\u00F3i \u0111\u00E3 \u0111\u01B0\u1EE3c x\u00E1c minh v\u1EABn c\u00F2n l\u01B0u. Kh\u1EDFi \u0111\u1ED9ng l\u1EA1i thi\u1EBFt b\u1ECB v\u00E0 th\u1EED m\u1EDF l\u1EA1i tr\u00ECnh c\u00E0i \u0111\u1EB7t c\u1EE7a Android.", "Paket yang diverifikasi masih tersimpan. Nyalakan ulang perangkat dan coba buka penginstal Android lagi.", "O pacote verificado ainda est\u00E1 salvo. Reinicie o dispositivo e tente abrir o instalador do Android novamente."),
        "The {0} package could not be prepared." to arrayOf("Hindi maihanda ang {0} package.", "{0} \uD328\uD0A4\uC9C0\uB97C \uC900\uBE44\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.", "{0}\u30D1\u30C3\u30B1\u30FC\u30B8\u3092\u6E96\u5099\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F\u3002", "{0} \u5305\u65E0\u6CD5\u51C6\u5907\u3002", "No se pudo preparar el paquete {0}.", "Kh\u00F4ng th\u1EC3 chu\u1EA9n b\u1ECB g\u00F3i {0}.", "Paket {0} tidak dapat dipersiapkan.", "O pacote {0} n\u00E3o p\u00F4de ser preparado."),
        "This add-on is not available for your device architecture or launcher version." to arrayOf("Ang add-on na ito ay hindi magagamit para sa arkitektura ng iyong device o bersyon ng launcher.", "\uC774 \uC560\uB4DC\uC628\uC740 \uC0AC\uC6A9\uC790\uC758 \uAE30\uAE30 \uC544\uD0A4\uD14D\uCC98\uB098 \uB7F0\uCC98 \uBC84\uC804\uC5D0\uC11C \uC0AC\uC6A9\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.", "\u3053\u306E\u30A2\u30C9\u30AA\u30F3\u306F\u3001\u3042\u306A\u305F\u306E\u30C7\u30D0\u30A4\u30B9\u306E\u30A2\u30FC\u30AD\u30C6\u30AF\u30C1\u30E3\u307E\u305F\u306F\u30E9\u30F3\u30C1\u30E3\u30FC\u306E\u30D0\u30FC\u30B8\u30E7\u30F3\u3067\u306F\u5229\u7528\u3067\u304D\u307E\u305B\u3093\u3002", "\u6B64\u63D2\u4EF6\u4E0D\u9002\u7528\u4E8E\u60A8\u7684\u8BBE\u5907\u67B6\u6784\u6216\u542F\u52A8\u5668\u7248\u672C\u3002", "Este complemento no est\u00E1 disponible para la arquitectura de su dispositivo o la versi\u00F3n del lanzador.", "Ti\u1EC7n \u00EDch b\u1ED5 sung n\u00E0y kh\u00F4ng kh\u1EA3 d\u1EE5ng cho ki\u1EBFn tr\u00FAc thi\u1EBFt b\u1ECB ho\u1EB7c phi\u00EAn b\u1EA3n tr\u00ECnh kh\u1EDFi ch\u1EA1y c\u1EE7a b\u1EA1n.", "Add-on ini tidak tersedia untuk arsitektur perangkat atau versi peluncur Anda.", "Este complemento n\u00E3o est\u00E1 dispon\u00EDvel para a arquitetura do seu dispositivo ou vers\u00E3o do launcher."),
        "This add-on isn't supported" to arrayOf("Ang add-on na ito ay hindi suportado", "\uC774 \uC560\uB4DC\uC628\uC740 \uC9C0\uC6D0\uB418\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\u3053\u306E\u30A2\u30C9\u30AA\u30F3\u306F\u30B5\u30DD\u30FC\u30C8\u3055\u308C\u3066\u3044\u307E\u305B\u3093\u3002", "\u6B64\u63D2\u4EF6\u4E0D\u53D7\u652F\u6301", "Este complemento no es compatible", "Ti\u1EC7n \u00EDch b\u1ED5 sung n\u00E0y kh\u00F4ng \u0111\u01B0\u1EE3c h\u1ED7 tr\u1EE3", "Add-on ini tidak didukung", "Este complemento n\u00E3o \u00E9 compat\u00EDvel"),
        "This add-on's verified history is unavailable. Try again when you're online." to arrayOf("Ang napatunayang kasaysayan ng add-on na ito ay hindi magagamit. Subukan muli kapag online ka.", "\uC774 \uC560\uB4DC\uC628\uC758 \uAC80\uC99D\uB41C \uAE30\uB85D\uC744 \uC0AC\uC6A9\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4. \uC628\uB77C\uC778 \uC0C1\uD0DC\uC77C \uB54C \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694.", "\u3053\u306E\u30A2\u30C9\u30AA\u30F3\u306E\u691C\u8A3C\u6E08\u307F\u5C65\u6B74\u306F\u5229\u7528\u3067\u304D\u307E\u305B\u3093\u3002\u30AA\u30F3\u30E9\u30A4\u30F3\u6642\u306B\u518D\u8A66\u884C\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "\u6B64\u63D2\u4EF6\u7684\u9A8C\u8BC1\u5386\u53F2\u4E0D\u53EF\u7528\u3002\u8BF7\u5728\u8054\u7F51\u65F6\u91CD\u8BD5\u3002", "No est\u00E1 disponible el historial verificado de este complemento. Intente nuevamente cuando est\u00E9 en l\u00EDnea.", "L\u1ECBch s\u1EED x\u00E1c minh c\u1EE7a ti\u1EC7n \u00EDch b\u1ED5 sung n\u00E0y kh\u00F4ng kh\u1EA3 d\u1EE5ng. Th\u1EED l\u1EA1i khi b\u1EA1n tr\u1EF1c tuy\u1EBFn.", "Riwayat terverifikasi add-on ini tidak tersedia. Coba lagi saat Anda online.", "O hist\u00F3rico verificado deste complemento n\u00E3o est\u00E1 dispon\u00EDvel. Tente novamente quando estiver online."),
        "This copy uses a different app identity or signing certificate. It may be a debug, locally signed, or repackaged build. Install the official Jester Mods release manually; Android may require this copy to be uninstalled first." to arrayOf("Ang kopyang ito ay gumagamit ng ibang pagkakakilanlan ng app o sertipiko ng pagpirma. Maaaring ito ay isang debug, lokal na pinirmahan, o muling binuong bersyon. I-install nang manu-mano ang opisyal na release ng Jester Mods; maaaring kailanganin ng Android na i-uninstall muna ang kopyang ito.", "\uC774 \uC0AC\uBCF8\uC740 \uB2E4\uB978 \uC571 \uC544\uC774\uB374\uD2F0\uD2F0 \uB610\uB294 \uC11C\uBA85 \uC778\uC99D\uC11C\uB97C \uC0AC\uC6A9\uD569\uB2C8\uB2E4. \uB514\uBC84\uADF8, \uB85C\uCEEC \uC11C\uBA85 \uB610\uB294 \uC7AC\uD328\uD0A4\uC9C0\uB41C \uBE4C\uB4DC\uC77C \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uACF5\uC2DD Jester Mods \uB9B4\uB9AC\uC2A4\uB97C \uC218\uB3D9\uC73C\uB85C \uC124\uCE58\uD558\uC138\uC694; Android\uC5D0\uC11C\uB294 \uC774 \uC0AC\uBCF8\uC744 \uBA3C\uC800 \uC81C\uAC70\uD574\uC57C \uD560 \uC218\uB3C4 \uC788\uC2B5\uB2C8\uB2E4.", "\u3053\u306E\u30B3\u30D4\u30FC\u306F\u7570\u306A\u308B\u30A2\u30D7\u30EA\u8B58\u5225\u307E\u305F\u306F\u7F72\u540D\u8A3C\u660E\u66F8\u3092\u4F7F\u7528\u3057\u3066\u3044\u307E\u3059\u3002\u30C7\u30D0\u30C3\u30B0\u3001\u30ED\u30FC\u30AB\u30EB\u7F72\u540D\u3001\u307E\u305F\u306F\u518D\u30D1\u30C3\u30B1\u30FC\u30B8\u5316\u3055\u308C\u305F\u30D3\u30EB\u30C9\u306E\u53EF\u80FD\u6027\u304C\u3042\u308A\u307E\u3059\u3002\u516C\u5F0F\u306E Jester Mods \u30EA\u30EA\u30FC\u30B9\u3092\u624B\u52D5\u3067\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3057\u3066\u304F\u3060\u3055\u3044\u3002Android \u3067\u306F\u3001\u3053\u306E\u30B3\u30D4\u30FC\u3092\u5148\u306B\u30A2\u30F3\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3059\u308B\u5FC5\u8981\u304C\u3042\u308B\u5834\u5408\u304C\u3042\u308A\u307E\u3059\u3002", "\u6B64\u526F\u672C\u4F7F\u7528\u4E86\u4E0D\u540C\u7684\u5E94\u7528\u8EAB\u4EFD\u6216\u7B7E\u540D\u8BC1\u4E66\u3002\u5B83\u53EF\u80FD\u662F\u8C03\u8BD5\u7248\u3001\u672C\u5730\u7B7E\u540D\u7248\u6216\u91CD\u65B0\u6253\u5305\u7684\u7248\u672C\u3002\u8BF7\u624B\u52A8\u5B89\u88C5\u5B98\u65B9\u7684 Jester Mods \u7248\u672C\uFF1BAndroid \u53EF\u80FD\u9700\u8981\u5148\u5378\u8F7D\u6B64\u526F\u672C\u3002", "Esta copia utiliza una identidad de aplicaci\u00F3n o certificado de firma diferente. Puede ser una versi\u00F3n de depuraci\u00F3n, firmada localmente o reempaquetada. Instale manualmente la versi\u00F3n oficial de Jester Mods; Android puede requerir que primero se desinstale esta copia.", "B\u1EA3n sao n\u00E0y s\u1EED d\u1EE5ng nh\u1EADn d\u1EA1ng \u1EE9ng d\u1EE5ng ho\u1EB7c ch\u1EE9ng ch\u1EC9 k\u00FD kh\u00E1c. N\u00F3 c\u00F3 th\u1EC3 l\u00E0 b\u1EA3n g\u1EE1 l\u1ED7i, k\u00FD c\u1EE5c b\u1ED9 ho\u1EB7c b\u1EA3n \u0111\u00F3ng g\u00F3i l\u1EA1i. C\u00E0i \u0111\u1EB7t th\u1EE7 c\u00F4ng phi\u00EAn b\u1EA3n ch\u00EDnh th\u1EE9c c\u1EE7a Jester Mods; Android c\u00F3 th\u1EC3 y\u00EAu c\u1EA7u g\u1EE1 c\u00E0i \u0111\u1EB7t b\u1EA3n sao n\u00E0y tr\u01B0\u1EDBc.", "Salinan ini menggunakan identitas aplikasi atau sertifikat penandatanganan yang berbeda. Ini mungkin versi debug, ditandatangani secara lokal, atau versi yang dikemas ulang. Instal rilis resmi Jester Mods secara manual; Android mungkin mengharuskan salinan ini dihapus terlebih dahulu.", "Esta c\u00F3pia usa uma identidade de aplicativo ou certificado de assinatura diferente. Pode ser uma vers\u00E3o de depura\u00E7\u00E3o, assinada localmente ou reembalada. Instale manualmente a vers\u00E3o oficial do Jester Mods; o Android pode exigir que esta c\u00F3pia seja desinstalada primeiro."),
        "This device could not complete the security check required for this add-on." to arrayOf("Hindi makumpleto ng device na ito ang kinakailangang security check para sa add-on na ito.", "\uC774 \uAE30\uAE30\uB294 \uC774 \uC560\uB4DC\uC628\uC5D0 \uD544\uC694\uD55C \uBCF4\uC548 \uAC80\uC0AC\uB97C \uC644\uB8CC\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.", "\u3053\u306E\u30C7\u30D0\u30A4\u30B9\u306F\u3001\u3053\u306E\u30A2\u30C9\u30AA\u30F3\u306B\u5FC5\u8981\u306A\u30BB\u30AD\u30E5\u30EA\u30C6\u30A3\u30C1\u30A7\u30C3\u30AF\u3092\u5B8C\u4E86\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F\u3002", "\u6B64\u8BBE\u5907\u65E0\u6CD5\u5B8C\u6210\u6B64\u63D2\u4EF6\u6240\u9700\u7684\u5B89\u5168\u68C0\u67E5\u3002", "Este dispositivo no pudo completar la verificaci\u00F3n de seguridad requerida para este complemento.", "Thi\u1EBFt b\u1ECB n\u00E0y kh\u00F4ng th\u1EC3 ho\u00E0n t\u1EA5t ki\u1EC3m tra b\u1EA3o m\u1EADt y\u00EAu c\u1EA7u cho ti\u1EC7n \u00EDch b\u1ED5 sung n\u00E0y.", "Perangkat ini tidak dapat menyelesaikan pemeriksaan keamanan yang diperlukan untuk add-on ini.", "Este dispositivo n\u00E3o conseguiu completar a verifica\u00E7\u00E3o de seguran\u00E7a necess\u00E1ria para este complemento."),
        "This device is not approved for this private add-on. Send the support code to the owner." to arrayOf("Ang device na ito ay hindi aprubado para sa pribadong add-on na ito. Ipadala ang support code sa may-ari.", "\uC774 \uAE30\uAE30\uB294 \uC774 \uAC1C\uC778 \uC560\uB4DC\uC628\uC5D0 \uC2B9\uC778\uB418\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4. \uC9C0\uC6D0 \uCF54\uB4DC\uB97C \uC18C\uC720\uC790\uC5D0\uAC8C \uBCF4\uB0B4\uC138\uC694.", "\u3053\u306E\u30C7\u30D0\u30A4\u30B9\u306F\u3001\u3053\u306E\u30D7\u30E9\u30A4\u30D9\u30FC\u30C8\u30A2\u30C9\u30AA\u30F3\u306B\u627F\u8A8D\u3055\u308C\u3066\u3044\u307E\u305B\u3093\u3002\u30B5\u30DD\u30FC\u30C8\u30B3\u30FC\u30C9\u3092\u6240\u6709\u8005\u306B\u9001\u4FE1\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "\u6B64\u8BBE\u5907\u672A\u83B7\u6279\u51C6\u4F7F\u7528\u6B64\u79C1\u4EBA\u63D2\u4EF6\u3002\u8BF7\u5C06\u652F\u6301\u4EE3\u7801\u53D1\u9001\u7ED9\u6240\u6709\u8005\u3002", "Este dispositivo no est\u00E1 aprobado para este complemento privado. Env\u00EDe el c\u00F3digo de soporte al propietario.", "Thi\u1EBFt b\u1ECB n\u00E0y kh\u00F4ng \u0111\u01B0\u1EE3c ph\u00EA duy\u1EC7t cho ti\u1EC7n \u00EDch b\u1ED5 sung ri\u00EAng t\u01B0 n\u00E0y. G\u1EEDi m\u00E3 h\u1ED7 tr\u1EE3 cho ch\u1EE7 s\u1EDF h\u1EEFu.", "Perangkat ini tidak disetujui untuk add-on pribadi ini. Kirim kode dukungan ke pemilik.", "Este dispositivo n\u00E3o est\u00E1 aprovado para este complemento privado. Envie o c\u00F3digo de suporte ao propriet\u00E1rio."),
        "This launcher can't update in place" to arrayOf("Ang launcher na ito ay hindi ma-update nang direkta", "\uC774 \uB7F0\uCC98\uB294 \uC81C\uC790\uB9AC\uC5D0\uC11C \uC5C5\uB370\uC774\uD2B8\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.", "\u3053\u306E\u30E9\u30F3\u30C1\u30E3\u30FC\u306F\u305D\u306E\u5834\u3067\u66F4\u65B0\u3067\u304D\u307E\u305B\u3093\u3002", "\u6B64\u542F\u52A8\u5668\u65E0\u6CD5\u539F\u5730\u66F4\u65B0", "Este lanzador no puede actualizarse en el lugar", "Tr\u00ECnh kh\u1EDFi ch\u1EA1y n\u00E0y kh\u00F4ng th\u1EC3 c\u1EADp nh\u1EADt t\u1EA1i ch\u1ED7", "Peluncur ini tidak dapat diperbarui di tempat", "Este launcher n\u00E3o pode atualizar no local"),
        "This launcher installation could not be trusted. Install an official, correctly signed build and try again." to arrayOf("Hindi mapagkakatiwalaan ang installation ng launcher na ito. Mag-install ng opisyal, tama ang pagkakapirma ng build at subukan muli.", "\uC774 \uB7F0\uCC98 \uC124\uCE58\uB294 \uC2E0\uB8B0\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4. \uACF5\uC2DD\uC73C\uB85C \uC62C\uBC14\uB974\uAC8C \uC11C\uBA85\uB41C \uBE4C\uB4DC\uB97C \uC124\uCE58\uD558\uACE0 \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694.", "\u3053\u306E\u30E9\u30F3\u30C1\u30E3\u30FC\u306E\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u306F\u4FE1\u983C\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F\u3002\u516C\u5F0F\u3067\u6B63\u3057\u304F\u7F72\u540D\u3055\u308C\u305F\u30D3\u30EB\u30C9\u3092\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3057\u3066\u518D\u8A66\u884C\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "\u65E0\u6CD5\u4FE1\u4EFB\u6B64\u542F\u52A8\u5668\u5B89\u88C5\u3002\u8BF7\u5B89\u88C5\u5B98\u65B9\u7684\u3001\u6B63\u786E\u7B7E\u540D\u7684\u7248\u672C\u5E76\u91CD\u8BD5\u3002", "No se pudo confiar en esta instalaci\u00F3n del lanzador. Instale una versi\u00F3n oficial con firma correcta e intente nuevamente.", "C\u00E0i \u0111\u1EB7t tr\u00ECnh kh\u1EDFi ch\u1EA1y n\u00E0y kh\u00F4ng \u0111\u00E1ng tin c\u1EADy. C\u00E0i \u0111\u1EB7t m\u1ED9t phi\u00EAn b\u1EA3n ch\u00EDnh th\u1EE9c, \u0111\u00FAng ch\u1EE9ng ch\u1EC9 v\u00E0 th\u1EED l\u1EA1i.", "Instalasi peluncur ini tidak dapat dipercaya. Instal versi resmi yang ditandatangani dengan benar dan coba lagi.", "A instala\u00E7\u00E3o deste launcher n\u00E3o p\u00F4de ser confi\u00E1vel. Instale uma vers\u00E3o oficial, corretamente assinada, e tente novamente."),
        "Try again. If it keeps happening, restart Jester Mods." to arrayOf("Subukang muli. Kung patuloy itong nangyayari, i-restart ang Jester Mods.", "\uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694. \uACC4\uC18D \uBC1C\uC0DD\uD558\uBA74 Jester Mods\uB97C \uC7AC\uC2DC\uC791\uD558\uC138\uC694.", "\u518D\u8A66\u884C\u3057\u3066\u304F\u3060\u3055\u3044\u3002\u554F\u984C\u304C\u7D9A\u304F\u5834\u5408\u306F\u3001Jester Mods \u3092\u518D\u8D77\u52D5\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "\u8BF7\u518D\u8BD5\u4E00\u6B21\u3002\u5982\u679C\u95EE\u9898\u6301\u7EED\uFF0C\u8BF7\u91CD\u542F Jester Mods\u3002", "Intenta de nuevo. Si sigue ocurriendo, reinicia Jester Mods.", "Th\u1EED l\u1EA1i. N\u1EBFu n\u00F3 ti\u1EBFp t\u1EE5c x\u1EA3y ra, kh\u1EDFi \u0111\u1ED9ng l\u1EA1i Jester Mods.", "Coba lagi. Jika terus terjadi, restart Jester Mods.", "Tente novamente. Se continuar acontecendo, reinicie o Jester Mods."),
        "Try the installation again. The verified download is still saved." to arrayOf("Subukang muli ang pag-install. Ang beripikadong download ay naka-save pa rin.", "\uC124\uCE58\uB97C \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694. \uAC80\uC99D\uB41C \uB2E4\uC6B4\uB85C\uB4DC\uB294 \uC5EC\uC804\uD788 \uC800\uC7A5\uB418\uC5B4 \uC788\uC2B5\uB2C8\uB2E4.", "\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3092\u3082\u3046\u4E00\u5EA6\u8A66\u3057\u3066\u304F\u3060\u3055\u3044\u3002\u78BA\u8A8D\u6E08\u307F\u306E\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u306F\u307E\u3060\u4FDD\u5B58\u3055\u308C\u3066\u3044\u307E\u3059\u3002", "\u8BF7\u91CD\u65B0\u5B89\u88C5\u3002\u5DF2\u4FDD\u5B58\u7ECF\u8FC7\u9A8C\u8BC1\u7684\u4E0B\u8F7D\u6587\u4EF6\u3002", "Intenta la instalaci\u00F3n otra vez. La descarga verificada a\u00FAn est\u00E1 guardada.", "Th\u1EED c\u00E0i \u0111\u1EB7t l\u1EA1i. T\u1EC7p t\u1EA3i xu\u1ED1ng \u0111\u00E3 \u0111\u01B0\u1EE3c x\u00E1c minh v\u1EABn \u0111\u01B0\u1EE3c l\u01B0u.", "Coba instalasi lagi. Unduhan yang sudah diverifikasi masih tersimpan.", "Tente a instala\u00E7\u00E3o novamente. O download verificado ainda est\u00E1 salvo."),
        "Unlock launcher access, then retry this update." to arrayOf("I-unlock ang access sa launcher, pagkatapos subukang muli ang update na ito.", "\uB7F0\uCC98 \uC811\uADFC\uC744 \uC7A0\uAE08 \uD574\uC81C\uD55C \uD6C4 \uC774 \uC5C5\uB370\uC774\uD2B8\uB97C \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694.", "\u30E9\u30F3\u30C1\u30E3\u30FC\u30A2\u30AF\u30BB\u30B9\u3092\u89E3\u9664\u3057\u3066\u304B\u3089\u3001\u3053\u306E\u30A2\u30C3\u30D7\u30C7\u30FC\u30C8\u3092\u518D\u8A66\u884C\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "\u89E3\u9501\u542F\u52A8\u5668\u8BBF\u95EE\u6743\u9650\uFF0C\u7136\u540E\u91CD\u8BD5\u6B64\u66F4\u65B0\u3002", "Desbloquea el acceso al lanzador, luego reintenta esta actualizaci\u00F3n.", "M\u1EDF quy\u1EC1n truy c\u1EADp tr\u00ECnh kh\u1EDFi ch\u1EA1y, sau \u0111\u00F3 th\u1EED c\u1EADp nh\u1EADt n\u00E0y l\u1EA1i.", "Buka akses peluncur, lalu coba perbarui ini lagi.", "Desbloqueie o acesso ao launcher e tente esta atualiza\u00E7\u00E3o novamente."),
        "Unsupported or unknown game architecture: {0}" to arrayOf("Hindi suportado o hindi kilalang arkitektura ng laro: {0}", "\uC9C0\uC6D0\uB418\uC9C0 \uC54A\uAC70\uB098 \uC54C \uC218 \uC5C6\uB294 \uAC8C\uC784 \uC544\uD0A4\uD14D\uCC98: {0}", "\u672A\u5BFE\u5FDC\u307E\u305F\u306F\u4E0D\u660E\u306A\u30B2\u30FC\u30E0\u30A2\u30FC\u30AD\u30C6\u30AF\u30C1\u30E3: {0}", "\u4E0D\u652F\u6301\u6216\u672A\u77E5\u7684\u6E38\u620F\u67B6\u6784\uFF1A{0}", "Arquitectura del juego no soportada o desconocida: {0}", "Ki\u1EBFn tr\u00FAc tr\u00F2 ch\u01A1i kh\u00F4ng \u0111\u01B0\u1EE3c h\u1ED7 tr\u1EE3 ho\u1EB7c kh\u00F4ng x\u00E1c \u0111\u1ECBnh: {0}", "Arsitektur game tidak didukung atau tidak dikenal: {0}", "Arquitetura de jogo n\u00E3o suportada ou desconhecida: {0}"),
        "Update available" to arrayOf("May magagamit na update", "\uC5C5\uB370\uC774\uD2B8 \uAC00\uB2A5", "\u30A2\u30C3\u30D7\u30C7\u30FC\u30C8\u5229\u7528\u53EF\u80FD", "\u6709\u53EF\u7528\u66F4\u65B0", "Actualizaci\u00F3n disponible", "C\u00F3 b\u1EA3n c\u1EADp nh\u1EADt", "Pembaruan tersedia", "Atualiza\u00E7\u00E3o dispon\u00EDvel"),
        "Update check" to arrayOf("Pagsusuri ng update", "\uC5C5\uB370\uC774\uD2B8 \uD655\uC778", "\u30A2\u30C3\u30D7\u30C7\u30FC\u30C8\u306E\u78BA\u8A8D", "\u68C0\u67E5\u66F4\u65B0", "Comprobaci\u00F3n de actualizaci\u00F3n", "Ki\u1EC3m tra c\u1EADp nh\u1EADt", "Pemeriksaan pembaruan", "Verifica\u00E7\u00E3o de atualiza\u00E7\u00E3o"),
        "Update check cancelled" to arrayOf("Kinansela ang pagsusuri ng update", "\uC5C5\uB370\uC774\uD2B8 \uD655\uC778 \uCDE8\uC18C\uB428", "\u30A2\u30C3\u30D7\u30C7\u30FC\u30C8\u78BA\u8A8D\u304C\u30AD\u30E3\u30F3\u30BB\u30EB\u3055\u308C\u307E\u3057\u305F", "\u5DF2\u53D6\u6D88\u66F4\u65B0\u68C0\u67E5", "Comprobaci\u00F3n de actualizaci\u00F3n cancelada", "H\u1EE7y ki\u1EC3m tra c\u1EADp nh\u1EADt", "Pemeriksaan pembaruan dibatalkan", "Verifica\u00E7\u00E3o de atualiza\u00E7\u00E3o cancelada"),
    )
}
